import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "./firebase";
import { Line } from "react-chartjs-2";
import { format } from "date-fns";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend);

const GraficoTrendMensile = () => {
  const [interventi, setInterventi] = useState([]);

  useEffect(() => {
    const fetchInterventi = async () => {
      const snap = await getDocs(collection(db, "INTERVENTI"));
      const dati = snap.docs.map(doc => doc.data());
      setInterventi(dati);
    };
    fetchInterventi();
  }, []);

  const conteggioPerMese = interventi.reduce((acc, i) => {
    const mese = format(i.data.toDate(), "yyyy-MM");
    acc[mese] = (acc[mese] || 0) + 1;
    return acc;
  }, {});

  const mesiOrdinati = Object.keys(conteggioPerMese).sort();
  const valori = mesiOrdinati.map(m => conteggioPerMese[m]);

  const data = {
    labels: mesiOrdinati,
    datasets: [
      {
        label: "Interventi mensili",
        data: valori,
        fill: false,
        borderColor: "#007bff",
        backgroundColor: "#007bff",
        tension: 0.3
      }
    ]
  };

  const options = {
    responsive: true,
    plugins: {
      legend: { position: "top" },
      tooltip: { mode: "index", intersect: false }
    },
    scales: {
      x: { title: { display: true, text: "Mese" } },
      y: { title: { display: true, text: "Numero interventi" }, beginAtZero: true }
    }
  };

  return (
    <div className="p-4 bg-light rounded">
      <h4 className="mb-3">📈 Andamento Interventi Mensili</h4>
      <Line data={data} options={options} />
    </div>
  );
};

export default GraficoTrendMensile;