import React, { useState, useEffect } from "react";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";
import { collection, getDocs } from "firebase/firestore";
import { db } from "./firebase";
import { format } from "date-fns";

const CalendarioInterventi = () => {
  const [interventi, setInterventi] = useState([]);
  const [dataSelezionata, setDataSelezionata] = useState(new Date());

  useEffect(() => {
    const fetchInterventi = async () => {
      const snap = await getDocs(collection(db, "INTERVENTI"));
      const dati = snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setInterventi(dati);
    };
    fetchInterventi();
  }, []);

  const eventiDelGiorno = interventi.filter(i =>
    format(i.data.toDate(), "yyyy-MM-dd") === format(dataSelezionata, "yyyy-MM-dd")
  );

  return (
    <div className="p-4 bg-light rounded">
      <h3 className="mb-4">📅 Calendario Interventi</h3>
      <Calendar onChange={setDataSelezionata} value={dataSelezionata} />

      <div className="mt-4">
        <h5>📌 Interventi del {format(dataSelezionata, "dd/MM/yyyy")}</h5>
        {eventiDelGiorno.length === 0 ? (
          <p className="text-muted">Nessun intervento registrato.</p>
        ) : (
          <ul>
            {eventiDelGiorno.map(i => (
              <li key={i.id}>
                <strong>{i.tipo}</strong> – {i.tecnico} su mezzo <em>{i.mezzoId}</em> ({i.urgente ? "🚨 Urgente" : "🛠️"})
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default CalendarioInterventi;